mapper.insert:
INSERT INTO TB_QUAL_DIAG_HISTORY (
    DIAG_ID, DM_ID, DIAG_TYPE, STATUS,
    TARGET_OBJ_LIST, SAMPLE_RATE, INCREMENTAL_YN, LAST_DIAG_DT,
    EXEC_USER_ID
) VALUES (
    #{diagId}, #{dmId}, #{diagType}, COALESCE(#{status}, 'READY'),
    #{targetObjList}, COALESCE(#{sampleRate}, 100),
    COALESCE(#{incrementalYn}, 'N'), #{lastDiagDt},
    #{execUserId}
)

mapper.select:
SELECT MAX(END_DT)
  FROM TB_QUAL_DIAG_HISTORY
 WHERE DM_ID     = #{dmId}
   AND DIAG_TYPE = #{diagType}
   AND STATUS    = 'DONE'

mapper.insert:
INSERT INTO TB_QUAL_RULE_RESULT (
    DIAG_ID, RULE_ID, OBJ_NM, ATTR_NM,
    TOTAL_CNT, VIOLATION_CNT, VIOLATION_RATE, SAMPLE_CNT, ERROR_MSG
) VALUES (
    #{diagId}, #{ruleId},
    COALESCE(#{objNm}, ''), COALESCE(#{attrNm}, ''),
    #{totalCnt}, #{violationCnt}, #{violationRate},
    COALESCE(#{sampleCnt}, 0), #{errorMsg}
)

INSERT INTO TB_QUAL_VIOLATION_SAMPLE (
    DIAG_ID, RULE_ID, OBJ_NM, ATTR_NM, SEQ,
    PK_VALUES, VIOLATING_VAL
) VALUES (
    #{diagId}, #{ruleId},
    COALESCE(#{objNm}, ''), COALESCE(#{attrNm}, ''),
    #{seq}, #{pkValues}, #{violatingVal}
)
